     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Arial, Helvetica, sans-serif;
       background:
         radial-gradient(circle at top, rgba(59, 130, 246, 0.2), transparent 32%),
         linear-gradient(180deg, #020617 0%, var(--bg) 100%);
       color: var(--text);
     }

     .skip-link {
       position: absolute;
       left: 1rem;
       top: -3rem;
       padding: 0.75rem 1rem;
       background: #ffffff;
       color: #111827;
       border-radius: 0.75rem;
       text-decoration: none;
       font-weight: 700;
       z-index: 10;
     }

     .skip-link:focus {
       top: 1rem;
     }

     main {
       display: grid;
       place-items: center;
       min-height: 100vh;
       padding: 2rem 1rem;
     }

     .support-card {
       width: min(100%, 36rem);
       padding: 2rem;
       border: 1px solid var(--panel-border);
       border-radius: 1.25rem;
       background: rgba(17, 24, 39, 0.92);
       box-shadow: 0 24px 60px var(--panel-shadow);
       backdrop-filter: blur(10px);
     }

     h1 {
       margin: 0 0 0.75rem;
       font-size: clamp(1.9rem, 4vw, 2.5rem);
       line-height: 1.1;
     }

     .intro {
       margin: 0 0 1.75rem;
       color: var(--muted);
       line-height: 1.6;
     }

     form {
       display: grid;
       gap: 1.25rem;
     }

     .form-field {
       display: grid;
       gap: 0.5rem;
     }

     label {
       font-weight: 700;
     }

     .required-indicator {
       color: #fbbf24;
     }

     input {
       width: 100%;
       padding: 0.9rem 1rem;
       border: 1px solid var(--input-border);
       border-radius: 0.9rem;
       background: var(--input);
       color: var(--text);
       font: inherit;
       transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
     }

     input::placeholder {
       color: #64748b;
     }

     input:focus {
       outline: 2px solid transparent;
       outline-offset: 2px;
       border-color: var(--accent);
       box-shadow: 0 0 0 3px rgba(96, 165, 250, 0.28);
     }

     .help-text,
     .error-text,
     .form-note {
       margin: 0;
       font-size: 0.95rem;
       line-height: 1.5;
     }

     .help-text,
     .form-note {
       color: var(--muted);
     }

     .error-text {
       color: var(--danger);
     }

     .form-field.invalid input {
       border-color: var(--danger-border);
       box-shadow: 0 0 0 3px rgba(251, 113, 133, 0.2);
     }

     .actions {
       display: flex;
       align-items: center;
       gap: 1rem;
       flex-wrap: wrap;
     }

     button {
       appearance: none;
       border: 0;
       border-radius: 999px;
       padding: 0.95rem 1.5rem;
       background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
       color: #eff6ff;
       font: inherit;
       font-weight: 700;
       cursor: pointer;
       transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
       box-shadow: 0 16px 36px rgba(37, 99, 235, 0.35);
     }

     button:hover {
       transform: translateY(-1px);
       filter: brightness(1.06);
     }

     button:focus {
       outline: 2px solid transparent;
       outline-offset: 3px;
       box-shadow:
         0 0 0 3px rgba(191, 219, 254, 0.45),
         0 16px 36px rgba(37, 99, 235, 0.35);
     }

     .status-message {
       margin: 0;
       padding: 0.85rem 1rem;
       border-radius: 0.9rem;
       border: 1px solid var(--success-border);
       background: var(--success-bg);
       color: #d1fae5;
     }

     [hidden] {
       display: none !important;
     }

     @media (max-width: 480px) {
       .support-card {
         padding: 1.5rem;
       }

       .actions {
         align-items: stretch;
       }

       button {
         width: 100%;
       }
     }

     @media (forced-colors: active) {
