   <script>
     const form = document.getElementById("support-form");
     const statusMessage = document.getElementById("form-status");

     const fields = {
       fullName: {
         input: document.getElementById("fullName"),
         error: document.getElementById("fullName-error"),
         validate(value) {
           if (!value.trim()) {
             return "Enter your full name.";
           }
           return "";
         }
       },
       email: {
         input: document.getElementById("email"),
         error: document.getElementById("email-error"),
         validate(value) {
           if (!value.trim()) {
             return "Enter your email address.";
           }

           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
           if (!emailPattern.test(value.trim())) {
             return "Enter a valid email address.";
           }
           return "";
         }
       },
       phone: {
         input: document.getElementById("phone"),
         error: document.getElementById("phone-error"),
         validate(value) {
           const trimmed = value.trim();
           if (!trimmed) {
             return "";
           }

           const phonePattern = /^[+]?[\d\s().-]{7,20}$/;
           if (!phonePattern.test(trimmed)) {
             return "Enter a valid phone number using digits and standard separators.";
           }
           return "";
         }
       }
     };

     function setFieldState(fieldName, message) {
       const { input, error } = fields[fieldName];
       const fieldWrapper = input.closest(".form-field");
       const helpId = fieldName === "phone" ? "phone-help " : "";

       if (message) {
         fieldWrapper.classList.add("invalid");
         input.setAttribute("aria-invalid", "true");
         error.textContent = message;
         error.hidden = false;
         input.setAttribute("aria-describedby", (helpId + error.id).trim());
       } else {
         fieldWrapper.classList.remove("invalid");
         input.removeAttribute("aria-invalid");
         error.textContent = "";
         error.hidden = true;
         input.setAttribute("aria-describedby", (helpId + error.id).trim());
       }
     }

     function validateField(fieldName) {
       const field = fields[fieldName];
       const message = field.validate(field.input.value);
       setFieldState(fieldName, message);
       return message;
     }

     Object.keys(fields).forEach((fieldName) => {
       const { input } = fields[fieldName];

       input.addEventListener("blur", () => {
         validateField(fieldName);
       });

       input.addEventListener("input", () => {
         if (input.getAttribute("aria-invalid") === "true") {
           validateField(fieldName);
         }
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();
       statusMessage.hidden = true;
       statusMessage.textContent = "";

       const errors = Object.keys(fields)
         .map((fieldName) => ({ fieldName, message: validateField(fieldName) }))
         .filter((result) => result.message);

       if (errors.length > 0) {
         fields[errors[0].fieldName].input.focus();
         return;
       }

       statusMessage.textContent = "Your support request has been prepared successfully.";
       statusMessage.hidden = false;
       form.reset();
       Object.keys(fields).forEach((fieldName) => setFieldState(fieldName, ""));
     });
   </script>
